-- What supabase/set_asks.sql does, tried inside the rolled-back transaction
-- of a dry run: nothing here is kept. Made-up accounts, made and gone with
-- the transaction, at Resend's test addresses (the checks' pool) unless
-- said: Ann asks; Bo (two versions), Cy, Dee and Eve (at example.com,
-- anybody else) each published a version of made-up set 99991-1, Ann one
-- too; Kit, under 13, made one the gallery may not list (trust.sql refuses
-- it a listing); Ann blocked Dee.
--
--   set -a; . ./.env; set +a
--   PG_MODULE=/tmp/pg/node_modules/pg/lib/index.js \
--     node tools/apply_sql.mjs supabase/set_asks.sql --dry --try=tools/set_asks_try.sql --table=talk_threads
--
-- Each statement is on one line: the dry run splits at a semicolon that
-- ends a line.
create function pg_temp.tries(statement text) returns text language plpgsql as $$ begin execute statement; return 'allowed'; exception when others then return 'refused: ' || sqlerrm; end $$;
grant execute on function pg_temp.tries(text) to anon, authenticated, service_role;
-- The columns and the table are new and empty; the functions the server's alone; the table nobody's.
select (select count(*) from public.talk_threads where ask_set is not null) as set_asks, (select count(*) from public.talk_ask_heard) as heard;
select p.proname, has_function_privilege('anon', p.oid, 'execute') as anon, has_function_privilege('authenticated', p.oid, 'execute') as signed_in, has_function_privilege('service_role', p.oid, 'execute') as server, p.prosecdef as security_definer from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('talk_set_ask', 'talk_set_asks', 'talk_ask_as', 'talk_pin_reply', 'talk_notice_rows') order by p.proname;
select has_table_privilege('anon', 'public.talk_ask_heard', 'select') as anon_reads, has_table_privilege('authenticated', 'public.talk_ask_heard', 'select') as signed_in_reads, has_table_privilege('service_role', 'public.talk_ask_heard', 'select') as server_reads, (select relrowsecurity from pg_class where oid = 'public.talk_ask_heard'::regclass) as row_security;
-- The made-up seven.
insert into auth.users (id, instance_id, aud, role, email, created_at, email_confirmed_at) values ('00000000-0000-4000-8000-0000000fc001', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'hub-try-ann@resend.dev', now() - interval '30 days', now()), ('00000000-0000-4000-8000-0000000fc002', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'hub-try-bo@resend.dev', now() - interval '30 days', now()), ('00000000-0000-4000-8000-0000000fc003', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'hub-try-cy@resend.dev', now() - interval '30 days', now()), ('00000000-0000-4000-8000-0000000fc004', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'hub-try-dee@resend.dev', now() - interval '30 days', now()), ('00000000-0000-4000-8000-0000000fc005', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'hub-try-eve@example.com', now() - interval '30 days', now()), ('00000000-0000-4000-8000-0000000fc006', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'hub-try-kit@resend.dev', now() - interval '30 days', now());
select public.answer_age('00000000-0000-4000-8000-0000000fc001', true)->>'over_13' as ann, public.answer_age('00000000-0000-4000-8000-0000000fc002', true)->>'over_13' as bo, public.answer_age('00000000-0000-4000-8000-0000000fc003', true)->>'over_13' as cy, public.answer_age('00000000-0000-4000-8000-0000000fc004', true)->>'over_13' as dee, public.answer_age('00000000-0000-4000-8000-0000000fc005', true)->>'over_13' as eve, public.answer_age('00000000-0000-4000-8000-0000000fc006', false)->>'over_13' as kit;
insert into public.people (account, handle, name) values ('00000000-0000-4000-8000-0000000fc001', 'hub-try-ann', 'Ann Try'), ('00000000-0000-4000-8000-0000000fc002', 'hub-try-bo', 'Bo Try'), ('00000000-0000-4000-8000-0000000fc003', 'hub-try-cy', 'Cy Try'), ('00000000-0000-4000-8000-0000000fc004', 'hub-try-dee', 'Dee Try'), ('00000000-0000-4000-8000-0000000fc005', 'hub-try-eve', 'Eve Try');
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, has_image) values ('HubTry0001', '00000000-0000-4000-8000-0000000fc002', 'Bo''s house', 'Bo Try', 40, 100, true, now() - interval '3 days', true, now(), true), ('HubTry0002', '00000000-0000-4000-8000-0000000fc002', 'Bo''s second house', 'Bo Try', 40, 100, true, now() - interval '2 days', true, now(), false), ('HubTry0003', '00000000-0000-4000-8000-0000000fc003', 'Cy''s house', 'Cy Try', 40, 100, true, now() - interval '1 day', true, now(), false), ('HubTry0004', '00000000-0000-4000-8000-0000000fc004', 'Dee''s house', 'Dee Try', 40, 100, true, now(), true, now(), false), ('HubTry0005', '00000000-0000-4000-8000-0000000fc005', 'Eve''s house', 'Eve Try', 40, 100, true, now(), false, now(), false), ('HubTry0006', '00000000-0000-4000-8000-0000000fc006', 'Kit''s house', null, 40, 100, false, null, true, now(), false), ('HubTry0007', '00000000-0000-4000-8000-0000000fc001', 'Ann''s house', 'Ann Try', 40, 100, true, now(), true, now(), false), ('HubTry0008', '00000000-0000-4000-8000-0000000fc003', 'Cy''s boat', 'Cy Try', 40, 100, true, now(), true, now(), false);
insert into public.share_versions (model, n, at, parts, bytes, has_image) values ('HubTry0001', 1, now() - interval '3 days', 40, 100, true), ('HubTry0002', 1, now(), 40, 100, false), ('HubTry0003', 1, now(), 40, 100, false), ('HubTry0004', 1, now(), 40, 100, false), ('HubTry0005', 1, now(), 40, 100, false), ('HubTry0006', 1, now(), 40, 100, false), ('HubTry0007', 1, now(), 40, 100, false), ('HubTry0007', 2, now(), 40, 100, false), ('HubTry0008', 1, now(), 40, 100, false);
insert into public.model_alt_sets (model, set_number, role, n, have) values ('HubTry0001', '99991-1', 'own', 0, 40), ('HubTry0002', '99991-1', 'own', 0, 40), ('HubTry0003', '99991-1', 'own', 0, 40), ('HubTry0004', '99991-1', 'own', 0, 40), ('HubTry0005', '99991-1', 'own', 0, 40), ('HubTry0006', '99991-1', 'own', 0, 40), ('HubTry0007', '99991-1', 'own', 0, 40), ('HubTry0008', '99992-1', 'own', 0, 40);
insert into public.blocks (blocker, blocked) values ('00000000-0000-4000-8000-0000000fc001', '00000000-0000-4000-8000-0000000fc004');
-- A page's keys are refused, signed out and signed in.
set local role anon;
select pg_temp.tries($q$select public.talk_set_ask('00000000-0000-4000-8000-0000000fc001', '99991-1', 'omr-99991-1', null, 1, 3, 'Forged', 'As Ann')$q$) as anon_asks_as_ann, pg_temp.tries($q$select public.talk_set_asks('99991-1', true, null)$q$) as anon_lists, pg_temp.tries($q$select * from public.talk_ask_heard$q$) as anon_reads_who_heard;
reset role;
set local role authenticated;
select pg_temp.tries($q$select public.talk_set_ask('00000000-0000-4000-8000-0000000fc002', '99991-1', 'omr-99991-1', null, 1, 3, 'Forged', 'As Bo')$q$) as signed_in_asks_as_bo, pg_temp.tries($q$select public.talk_notice_rows('00000000-0000-4000-8000-0000000fc002', now() - interval '1 day', now())$q$) as signed_in_reads_bos_notices, pg_temp.tries($q$insert into public.talk_ask_heard (thread, account) values (1, '00000000-0000-4000-8000-0000000fc002')$q$) as signed_in_writes_heard;
reset role;
-- Ann asks about step 3 of set 99991-1, the step drawn from Bo's version (LDraw's model as it is). Before: none listed.
select jsonb_array_length(public.talk_set_asks('99991-1', true, null)) as listed_before;
create temporary table a_ask on commit drop as select public.talk_set_ask('00000000-0000-4000-8000-0000000fc001', '99991-1', 'omr-99991-1', 'HubTry0001', 1, 3, 'Where does the hinge go?', 'At step 3 the door hinge will not sit: which way round is it?') as r;
select r->'thread'->>'board' as board, r->'ask'->>'set' as set, r->'ask'->>'library' as library, r->'ask'->>'drawn' as drawn, r->'ask'->>'version' as version, r->'ask'->>'step' as step, r->'ask'->>'model' as model, r->>'heard' as heard, r ? 'refused' as refused from a_ask;
-- Who heard: Bo once for his two versions, Cy; not Ann (her own ask), Dee (Ann blocked her), Kit (under 13), Eve (anybody else's pool).
select string_agg(p.handle, ', ' order by p.handle) as heard, count(*) as n from public.talk_ask_heard h left join public.people p on p.account = h.account where h.thread = (select (r->'thread'->>'id')::bigint from a_ask);
select (select count(*) from public.talk_ask_heard h where h.account = '00000000-0000-4000-8000-0000000fc006') as kit_heard, (select count(*) from public.talk_ask_heard h where h.account = '00000000-0000-4000-8000-0000000fc005') as eve_heard, (select count(*) from public.talk_ask_heard h where h.account = '00000000-0000-4000-8000-0000000fc004') as dee_heard;
-- What Bo is told: a mention, its ask said; the kind he chooses mentions by; Kit and Ann told nothing.
select r.kind, public.notification_kind(r.kind) as chosen_as, public.notification_group(r.kind, r.model, r.item) as grouped, r.item->>'title' as title, r.item->'ask'->>'set' as set, r.item->'ask'->>'step' as step, r.item->'by'->>'handle' as by from public.talk_notice_rows('00000000-0000-4000-8000-0000000fc002', now() - interval '1 hour', now() + interval '1 hour') r;
select (select count(*) from public.notification_rows('00000000-0000-4000-8000-0000000fc002', now() - interval '1 hour', now() + interval '1 hour') r where r.item ? 'ask') as bo_in_notifications, (select count(*) from public.talk_notice_rows('00000000-0000-4000-8000-0000000fc006', now() - interval '1 hour', now() + interval '1 hour')) as kit_told, (select count(*) from public.talk_notice_rows('00000000-0000-4000-8000-0000000fc001', now() - interval '1 hour', now() + interval '1 hour')) as ann_told;
-- The set's page lists it, open, in the checks' pool alone.
select jsonb_array_length(public.talk_set_asks('99991-1', true, null)) as listed, public.talk_set_asks('99991-1', true, null)->0->>'answered' as answered, public.talk_set_asks('99991-1', true, null)->0->>'step' as step, public.talk_set_asks('99991-1', true, null)->0->'by'->>'handle' as by, jsonb_array_length(public.talk_set_asks('99991-1', false, null)) as in_peoples_pool, jsonb_array_length(public.talk_set_asks('99992-1', true, null)) as other_set;
-- What is refused: Kit (under 13); nobody; a set that is no number; a drawn model that is no version of the set; a version not there; LDraw's file at version 2; step 0.
select public.talk_set_ask('00000000-0000-4000-8000-0000000fc006', '99991-1', 'omr-99991-1', null, 1, 3, 'Kit asks', 'Under thirteen')->>'refused' as kit_under_13, public.talk_set_ask(null, '99991-1', 'omr-99991-1', null, 1, 3, 'Nobody', 'Signed out')->>'refused' as nobody, public.talk_set_ask('00000000-0000-4000-8000-0000000fc001', 'NOT A SET', 'omr-99991-1', null, 1, 3, 'Bad set', 'Bad')->>'refused' as bad_set, public.talk_set_ask('00000000-0000-4000-8000-0000000fc001', '99991-1', 'omr-99991-1', 'HubTry0008', 1, 3, 'Boat', 'Not a version of it')->>'refused' as other_sets_model, public.talk_set_ask('00000000-0000-4000-8000-0000000fc001', '99991-1', 'omr-99991-1', 'HubTry0001', 9, 3, 'Nine', 'Version nine')->>'refused' as no_version, public.talk_set_ask('00000000-0000-4000-8000-0000000fc001', '99991-1', 'omr-99991-1', null, 2, 3, 'Two', 'LDraw has one')->>'refused' as ldraw_version_2, public.talk_set_ask('00000000-0000-4000-8000-0000000fc001', '99991-1', 'omr-99991-1', null, 1, 0, 'Nought', 'Step 0')->>'refused' as step_zero;
-- Bo answers on a part; then it is answered. Ann's own reply alone would not be: she asked it.
select public.talk_reply('00000000-0000-4000-8000-0000000fc001', (select (r->'thread'->>'id')::bigint from a_ask), 'Still stuck, a picture would help.')->'post'->>'id' is not null as ann_replied, public.talk_set_asks('99991-1', true, null)->0->>'answered' as answered_by_her_own_reply;
create temporary table a_bo on commit drop as select public.talk_pin_reply('00000000-0000-4000-8000-0000000fc002', (select (r->'thread'->>'id')::bigint from a_ask), 'The pin side faces the wall: this one.', '{"part":"3830.dat","colour":15,"at":[0,-24,0],"near":[],"full":true}') as r;
select r->'post'->'pin'->>'part' as on_part, r ? 'refused' as refused, public.talk_set_asks('99991-1', true, null)->0->>'answered' as answered, (public.talk_set_asks('99991-1', true, null)->0->>'replies')::int as replies from a_bo;
-- (Ann follows her thread, as talk_start makes its starter, so she is told
-- of Bo's answer as of any reply: not seen here, where one transaction's
-- now() dates the follow and the answer alike.)
select count(*) as ann_follows from public.talk_follows f where f.account = '00000000-0000-4000-8000-0000000fc001' and f.thread = (select (r->'thread'->>'id')::bigint from a_ask);
-- Blocks hold: Bo blocks Ann; her ask leaves his list of the set's asks, and his notices.
insert into public.blocks (blocker, blocked) values ('00000000-0000-4000-8000-0000000fc002', '00000000-0000-4000-8000-0000000fc001');
select jsonb_array_length(public.talk_set_asks('99991-1', true, '00000000-0000-4000-8000-0000000fc002')) as bos_list, (select count(*) from public.talk_notice_rows('00000000-0000-4000-8000-0000000fc002', now() - interval '1 hour', now() + interval '1 hour')) as bos_notices;
delete from public.blocks where blocker = '00000000-0000-4000-8000-0000000fc002';
-- A studio ask is as it was: Ann asks about her own model.
select r->'ask'->>'model' as model, r->'ask'->>'set' is null as no_set, r->'ask'->>'version' as version from (select public.talk_ask('00000000-0000-4000-8000-0000000fc001', 'HubTry0007', 2, 1, null, 'My own house', 'A studio ask, as before') as r) x;
-- The drawn version gone: the ask stays, the set's, drawn from LDraw's file.
delete from public.shared_models where id = 'HubTry0001';
select t.ask_set, t.ask_drawn is null as drawn_gone, public.talk_ask_as(t)->>'drawn' is null as said_undrawn, public.talk_ask_as(t)->>'library' as library from public.talk_threads t where t.id = (select (r->'thread'->>'id')::bigint from a_ask);
